class EventStore:
    def __init__(self):
        self._events = {}

    def record(self, user, value):
        if user not in self._events:
            self._events[user] = []
        self._events[user].append(value)

    def latest(self, user):
        if user in self._events:
            return self._events[user][-1]
        return None

    def replace_latest(self, user, value):
        if user in self._events and self._events[user]:
            old_value = self._events[user][-1]
            self._events[user][-1] = value
            return old_value
        return None
